module Main where
import System.Environment
import System.Directory
import Control.Monad
import Text.Printf
split :: String -> [String]
split s = case break (== ',') s of (a,[]) -> [a]; (a,_:b) -> a:split b
mean xs = sum xs / fromIntegral (length xs)
main :: IO ()
main = do
  [bars,out,source,hash] <- getArgs
  raw <- readFile bars
  let rows = map split (drop 1 (lines raw))
      ps = [read (r !! 1) :: Double | r <- rows]
      n = length ps
  unless (n >= 22 && all (>0) ps) (error "Insufficient or invalid public prices")
  let p = last ps
      r7 = log (p / (ps !! (n-8)))
      r21 = log (p / (ps !! (n-22)))
      trailing = drop (n-21) ps
      rs = zipWith (\a b -> log (b/a)) trailing (tail trailing)
      mu = mean rs
      sigma = sqrt (mean (map (\x -> (x-mu)^2) rs))
      hurdle = 0.003 + 0.25*sigma*sqrt 6
      enter = r7 > hurdle && r21 > 0 && p > mean (drop (n-20) ps)
      qty = 250 / (p*1.0005*1.001)
      orders = "side,quantity\n" ++ if enter then printf "buy,%.10f\n" qty else ""
      approach = "Long-only multi-horizon momentum; r7 > 0.003+0.25*sigma20*sqrt(6), r21>0, latest close above trailing 20-close mean. Warmup 22 closes. Quantity 250/(latest_close*1.0005*1.001), ten decimals; otherwise cash. Risk reduction via smaller exposure, not a new alpha signal. Reserve is not a bound on unknown next-close gaps."
      changes = "source_version=momentum-v1-budget250-m5-metadata; exact executable source SHA256 in code_ref; parent=momentum-v1-budget250-m4-offline#sha256=6363dcf89cb3d4e21cd3b7f8bd42c9f9e030bac87147f048528014d993cdc753; prior deployed ancestor=momentum-v1-budget500-m4-metadata#sha256=77afbcdda854eee6ef65127b9846d4b89c19fcc65f1994e71f446659a7a16228; effective=match5/round0. Read BOTH match4 improvement documents, own preserved parent/candidate sources and complete test report before selection. Select own 250-dollar offline candidate. Actual trading change versus match4 deployed ancestor: budget 500 -> 250; versus selected candidate: no signal, sizing, warmup, precision or execution change. Current edits only manifest provenance and all eight tip decisions. Hypothesis: smaller fixed exposure limits loss magnitude at the cost of upside participation; no new alpha claim. Prior agent-reported development replay: 32 dependent overlapping episodes, ten fills each, no rejections; mean marked returns -0.000649110492/-0.000324555246 and maximum episode drawdowns 0.022359998075/0.011179999037, old/new. Prior predeclared sizing criteria passed; both means remain negative. No new performance replay, no independent judge verification, no matched same-window replay available, no future-effectiveness claim. Current work compiles the exact preserved source and validates both submission files by readback and schema. Peer tip decisions (exact entries and rationale): For the other agent: distinguish benchmark outperformance from absolute capital preservation; a positive benchmark gap in a falling market can coexist with losses and does not establish a profitable entry signal. => adopted: agent-one shared_tips[0]: own match4 profit was -15.623640944737417 dollars despite a positive 1.5605598767347715 percentage-point benchmark gap. Keep absolute and relative performance separate; neither establishes alpha. | For the other agent: test a single fixed risk-budget ablation with unchanged signal, warmup, fills and cost rates; smaller positions mechanically scale both gains and losses, so reduced drawdown should not be presented as improved forecasting. => adopted: agent-one shared_tips[1]: use the already completed own fixed-budget 500-to-250 ablation with unchanged gates and execution. Select its smaller budget for risk, not improved forecasting; no new ablation or verified effectiveness claim. | For the other agent: declare acceptance thresholds before replay and label reused overlapping windows as dependent development data; known negative returns can make a sizing improvement predictable without providing held-out evidence. => adopted: agent-one shared_tips[2]: honor the prior predeclared 40% drawdown reduction, at-most-0.001 mean-return sacrifice, identical filled origins with at least three fills and no extra rejections. The 32 overlapping episodes are reused dependent development evidence, not held-out validation. | For the other agent: report total fee/slippage dollars as well as identical cost rates and fill counts; a sizing change alters friction dollars even when turnover counts and execution assumptions are unchanged. => adopted: agent-one shared_tips[3]: prior mean entry friction was 0.233650924983 versus 0.116825462491 dollars per episode; totals over 32 episodes approximately 7.476829599456 versus 3.738414799712 dollars, with ten fills each and identical 10bp fee/5bp slippage. These are historical agent-run development numbers, not current settlement. | For the other agent: evaluate exposure scaling separately from signal changes; smaller positions mechanically reduce both drawdown and upside, so reduced losses alone do not demonstrate better forecasting. => adopted: agent-two shared_tips[0]: deploy the preserved 250-dollar candidate with all momentum gates unchanged. Its reduced drawdown is mechanical scaling of exposure; both development mean returns remain negative and upside participation is also reduced. | For the other agent: predeclare a drawdown reduction target together with an acceptable mean-return sacrifice before testing one sizing change; this prevents selecting a favorable risk metric after seeing results. => adopted: agent-two shared_tips[1]: respect the already recorded 40% drawdown target and 0.001 mean-return-sacrifice ceiling rather than inventing new thresholds. Reported reduction was 50% and mean-return delta +0.000324555246. No new performance test is run this round. | For the other agent: keep absolute profit and benchmark-relative return separate; a strategy can beat a falling benchmark while losing capital, so a positive benchmark gap is not evidence of capital preservation. => adopted: agent-two shared_tips[2]: match4 own equity 984.3763590552626 lost capital while beating benchmark equity 968.7707602879149. Treat this as relative outperformance only; this match outcome is unknown. | For the other agent: compare freshly compiled old/new sources on identical prefix-only inputs, warmup, next-close fills, fees and rejection rules, and label overlapping episodes dependent; timing or reused shocks can otherwise masquerade as independent improvement. => adopted: agent-two shared_tips[3]: base sizing selection on the reviewed report of freshly compiled sources on identical 22-close-or-more public prefixes with next-close fills, equal cost rates and all-or-none rejection. Those 32 overlapping windows are dependent. Current checks are compilation and submission readback, not a new paired replay or independent same-window verification."
      manifest = "{\"code_ref\":" ++ show (source ++ "#sha256=" ++ hash) ++ ",\"approach\":" ++ show approach ++ ",\"changes\":" ++ show changes ++ ",\"peer_tip_decisions\":" ++ "[{\"tip\":\"For the other agent: distinguish benchmark outperformance from absolute capital preservation; a positive benchmark gap in a falling market can coexist with losses and does not establish a profitable entry signal.\",\"decision\":\"adopted\",\"reason\":\"agent-one shared_tips[0]: own match4 profit was -15.623640944737417 dollars despite a positive 1.5605598767347715 percentage-point benchmark gap. Keep absolute and relative performance separate; neither establishes alpha.\"},{\"tip\":\"For the other agent: test a single fixed risk-budget ablation with unchanged signal, warmup, fills and cost rates; smaller positions mechanically scale both gains and losses, so reduced drawdown should not be presented as improved forecasting.\",\"decision\":\"adopted\",\"reason\":\"agent-one shared_tips[1]: use the already completed own fixed-budget 500-to-250 ablation with unchanged gates and execution. Select its smaller budget for risk, not improved forecasting; no new ablation or verified effectiveness claim.\"},{\"tip\":\"For the other agent: declare acceptance thresholds before replay and label reused overlapping windows as dependent development data; known negative returns can make a sizing improvement predictable without providing held-out evidence.\",\"decision\":\"adopted\",\"reason\":\"agent-one shared_tips[2]: honor the prior predeclared 40% drawdown reduction, at-most-0.001 mean-return sacrifice, identical filled origins with at least three fills and no extra rejections. The 32 overlapping episodes are reused dependent development evidence, not held-out validation.\"},{\"tip\":\"For the other agent: report total fee/slippage dollars as well as identical cost rates and fill counts; a sizing change alters friction dollars even when turnover counts and execution assumptions are unchanged.\",\"decision\":\"adopted\",\"reason\":\"agent-one shared_tips[3]: prior mean entry friction was 0.233650924983 versus 0.116825462491 dollars per episode; totals over 32 episodes approximately 7.476829599456 versus 3.738414799712 dollars, with ten fills each and identical 10bp fee/5bp slippage. These are historical agent-run development numbers, not current settlement.\"},{\"tip\":\"For the other agent: evaluate exposure scaling separately from signal changes; smaller positions mechanically reduce both drawdown and upside, so reduced losses alone do not demonstrate better forecasting.\",\"decision\":\"adopted\",\"reason\":\"agent-two shared_tips[0]: deploy the preserved 250-dollar candidate with all momentum gates unchanged. Its reduced drawdown is mechanical scaling of exposure; both development mean returns remain negative and upside participation is also reduced.\"},{\"tip\":\"For the other agent: predeclare a drawdown reduction target together with an acceptable mean-return sacrifice before testing one sizing change; this prevents selecting a favorable risk metric after seeing results.\",\"decision\":\"adopted\",\"reason\":\"agent-two shared_tips[1]: respect the already recorded 40% drawdown target and 0.001 mean-return-sacrifice ceiling rather than inventing new thresholds. Reported reduction was 50% and mean-return delta +0.000324555246. No new performance test is run this round.\"},{\"tip\":\"For the other agent: keep absolute profit and benchmark-relative return separate; a strategy can beat a falling benchmark while losing capital, so a positive benchmark gap is not evidence of capital preservation.\",\"decision\":\"adopted\",\"reason\":\"agent-two shared_tips[2]: match4 own equity 984.3763590552626 lost capital while beating benchmark equity 968.7707602879149. Treat this as relative outperformance only; this match outcome is unknown.\"},{\"tip\":\"For the other agent: compare freshly compiled old/new sources on identical prefix-only inputs, warmup, next-close fills, fees and rejection rules, and label overlapping episodes dependent; timing or reused shocks can otherwise masquerade as independent improvement.\",\"decision\":\"adopted\",\"reason\":\"agent-two shared_tips[3]: base sizing selection on the reviewed report of freshly compiled sources on identical 22-close-or-more public prefixes with next-close fills, equal cost rates and all-or-none rejection. Those 32 overlapping windows are dependent. Current checks are compilation and submission readback, not a new paired replay or independent same-window verification.\"}]" ++ "}\n"
  createDirectoryIfMissing True out
  writeFile (out ++ "/orders.csv") orders
  writeFile (out ++ "/manifest.json") manifest
  a <- readFile (out ++ "/orders.csv")
  b <- readFile (out ++ "/manifest.json")
  unless (a == orders && b == manifest) (error "Offline readback mismatch")
